-- GSWAU full database setup. Paste into Supabase > SQL Editor and click Run (once, on an empty project).

-- 1. Private bucket for book/course files
insert into storage.buckets (id, name, public) values ('product-files', 'product-files', false) on conflict (id) do nothing;

-- 2. Schema
create type public.app_role as enum ('admin', 'user');
create type public.product_type as enum ('ebook', 'audiobook', 'course', 'bundle');
create type public.lesson_type as enum ('video', 'audio', 'text');

create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path = public as $$
begin new.updated_at = now(); return new; end; $$;

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text, avatar_url text, email text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
grant select, update on public.profiles to authenticated;
grant all on public.profiles to service_role;
alter table public.profiles enable row level security;

create table public.user_roles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade not null,
  role public.app_role not null, unique (user_id, role)
);
grant select on public.user_roles to authenticated;
grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;

create or replace function public.has_role(_user_id uuid, _role public.app_role) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.user_roles where user_id = _user_id and role = _role) $$;

create policy "own roles" on public.user_roles for select to authenticated using (user_id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "profiles read" on public.profiles for select to authenticated using (id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "profiles update own" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name, email) values (new.id, new.raw_user_meta_data->>'full_name', new.email);
  insert into public.user_roles (user_id, role) values (new.id, 'user');
  if (select count(*) from public.user_roles where role = 'admin') = 0 then
    insert into public.user_roles (user_id, role) values (new.id, 'admin');
  end if;
  return new;
end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create table public.products (
  id uuid primary key default gen_random_uuid(),
  type public.product_type not null default 'ebook',
  title text not null, subtitle text not null default '', slug text not null unique,
  description text not null default '', cover_image_url text,
  price_cents integer not null default 0,
  is_free boolean not null default false, is_lead_magnet boolean not null default false,
  is_published boolean not null default true, is_featured boolean not null default false,
  buy_url text, file_path text, position integer not null default 0,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create trigger products_touch before update on public.products for each row execute procedure public.touch_updated_at();
grant select on public.products to anon;
grant select, insert, update, delete on public.products to authenticated;
grant all on public.products to service_role;
alter table public.products enable row level security;
create policy "products public read" on public.products for select to anon, authenticated using (is_published or public.has_role(auth.uid(),'admin'));
create policy "products admin write" on public.products for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create table public.bundle_items (
  bundle_id uuid not null references public.products(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete cascade,
  primary key (bundle_id, product_id)
);
grant select on public.bundle_items to anon;
grant select, insert, update, delete on public.bundle_items to authenticated;
grant all on public.bundle_items to service_role;
alter table public.bundle_items enable row level security;
create policy "bundle read" on public.bundle_items for select to anon, authenticated using (true);
create policy "bundle admin" on public.bundle_items for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create table public.entitlements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null, product_id uuid not null references public.products(id) on delete cascade,
  granted_at timestamptz not null default now(), unique (user_id, product_id)
);
grant select, insert, delete on public.entitlements to authenticated;
grant all on public.entitlements to service_role;
alter table public.entitlements enable row level security;
create policy "ent read" on public.entitlements for select to authenticated using (user_id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "ent admin" on public.entitlements for insert to authenticated with check (public.has_role(auth.uid(),'admin'));
create policy "ent admin del" on public.entitlements for delete to authenticated using (public.has_role(auth.uid(),'admin'));

create or replace function public.has_access(_product uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(auth.uid(),'admin')
    or exists (select 1 from public.products p where p.id = _product and p.is_free)
    or exists (select 1 from public.entitlements e where e.user_id = auth.uid() and (e.product_id = _product
       or exists (select 1 from public.bundle_items b where b.bundle_id = e.product_id and b.product_id = _product))) $$;

create table public.modules (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.products(id) on delete cascade,
  title text not null, position integer not null default 0, created_at timestamptz not null default now()
);
grant select on public.modules to anon;
grant select, insert, update, delete on public.modules to authenticated;
grant all on public.modules to service_role;
alter table public.modules enable row level security;
create policy "modules read" on public.modules for select to anon, authenticated using (true);
create policy "modules admin" on public.modules for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create table public.lessons (
  id uuid primary key default gen_random_uuid(),
  module_id uuid not null references public.modules(id) on delete cascade,
  title text not null, type public.lesson_type not null default 'video',
  content_url text, body text, duration_minutes integer, is_preview boolean not null default false,
  position integer not null default 0, created_at timestamptz not null default now()
);
grant select, insert, update, delete on public.lessons to authenticated;
grant all on public.lessons to service_role;
alter table public.lessons enable row level security;
create policy "lessons read" on public.lessons for select to authenticated using (
  is_preview or public.has_access((select m.course_id from public.modules m where m.id = module_id)));
create policy "lessons admin" on public.lessons for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create or replace function public.course_outline(_course uuid)
returns table (lesson_id uuid, module_id uuid, title text, lesson_type public.lesson_type, duration_minutes integer, is_preview boolean, sort_order integer)
language sql stable security definer set search_path = public as $$
  select l.id, l.module_id, l.title, l.type, l.duration_minutes, l.is_preview, l.position
  from public.lessons l join public.modules m on m.id = l.module_id where m.course_id = _course order by m.position, l.position $$;
grant execute on function public.course_outline(uuid) to anon, authenticated;

create table public.lesson_progress (
  user_id uuid not null, lesson_id uuid not null references public.lessons(id) on delete cascade,
  completed_at timestamptz not null default now(), primary key (user_id, lesson_id)
);
grant select, insert, delete on public.lesson_progress to authenticated;
grant all on public.lesson_progress to service_role;
alter table public.lesson_progress enable row level security;
create policy "progress own" on public.lesson_progress for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

create table public.leads (
  id uuid primary key default gen_random_uuid(),
  email text not null, source text not null default 'free-chapter', created_at timestamptz not null default now()
);
grant insert on public.leads to anon, authenticated;
grant select, delete on public.leads to authenticated;
grant all on public.leads to service_role;
alter table public.leads enable row level security;
create policy "leads insert" on public.leads for insert to anon, authenticated with check (length(email) between 3 and 255 and email like '%@%');
create policy "leads admin read" on public.leads for select to authenticated using (public.has_role(auth.uid(),'admin'));
create policy "leads admin del" on public.leads for delete to authenticated using (public.has_role(auth.uid(),'admin'));

create table public.testimonials (
  id uuid primary key default gen_random_uuid(),
  name text not null, location text, quote text not null, rating integer not null default 5,
  product_id uuid references public.products(id) on delete set null,
  is_published boolean not null default false, user_id uuid,
  created_at timestamptz not null default now()
);
grant select, insert on public.testimonials to anon, authenticated;
grant update, delete on public.testimonials to authenticated;
grant all on public.testimonials to service_role;
alter table public.testimonials enable row level security;
create policy "testimonials read" on public.testimonials for select to anon, authenticated using (is_published or public.has_role(auth.uid(),'admin'));
create policy "testimonials submit" on public.testimonials for insert to authenticated with check (user_id = auth.uid() and is_published = false and rating between 1 and 5);
create policy "testimonials admin" on public.testimonials for update to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "testimonials admin del" on public.testimonials for delete to authenticated using (public.has_role(auth.uid(),'admin'));

create table public.blog_posts (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique, title text not null, excerpt text not null default '', body text not null default '',
  cover_image_url text, is_published boolean not null default false, published_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create trigger blog_touch before update on public.blog_posts for each row execute procedure public.touch_updated_at();
grant select on public.blog_posts to anon;
grant select, insert, update, delete on public.blog_posts to authenticated;
grant all on public.blog_posts to service_role;
alter table public.blog_posts enable row level security;
create policy "blog read" on public.blog_posts for select to anon, authenticated using (is_published or public.has_role(auth.uid(),'admin'));
create policy "blog admin" on public.blog_posts for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create policy "files admin write" on storage.objects for all to authenticated
  using (bucket_id = 'product-files' and public.has_role(auth.uid(),'admin'))
  with check (bucket_id = 'product-files' and public.has_role(auth.uid(),'admin'));
create policy "files entitled read" on storage.objects for select to authenticated
  using (bucket_id = 'product-files' and exists (select 1 from public.products p where p.file_path = name and public.has_access(p.id)));

-- 3. Subscribers, ratings, podcast
-- Subscriber access, product details, per-product review ratings and the podcast.

alter table public.products
  add column file_size_label text,
  add column length_label text,
  add column gallery_urls text[] not null default '{}',
  add column included_with_subscription boolean not null default false;

create table public.subscriptions (
  user_id uuid primary key references auth.users(id) on delete cascade,
  status text not null default 'active' check (status in ('active', 'canceled')),
  started_at timestamptz not null default now(),
  current_period_end timestamptz,
  provider text, provider_ref text
);
grant select, insert, update, delete on public.subscriptions to authenticated;
grant all on public.subscriptions to service_role;
alter table public.subscriptions enable row level security;
create policy "subscriptions read" on public.subscriptions for select to authenticated using (user_id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "subscriptions admin" on public.subscriptions for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

create or replace function public.has_subscription(_user uuid default auth.uid()) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.subscriptions s
    where s.user_id = _user and s.status = 'active' and (s.current_period_end is null or s.current_period_end > now())) $$;
grant execute on function public.has_subscription(uuid) to authenticated;

create or replace function public.has_access(_product uuid) returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(auth.uid(),'admin')
    or exists (select 1 from public.products p where p.id = _product and p.is_free)
    or exists (select 1 from public.products p where p.id = _product and p.included_with_subscription and public.has_subscription(auth.uid()))
    or exists (select 1 from public.entitlements e where e.user_id = auth.uid() and (e.product_id = _product
       or exists (select 1 from public.bundle_items b where b.bundle_id = e.product_id and b.product_id = _product))) $$;

create view public.product_ratings as
  select product_id, count(*)::int as review_count, round(avg(rating)::numeric, 1) as average,
    count(*) filter (where rating = 5)::int as stars_5, count(*) filter (where rating = 4)::int as stars_4,
    count(*) filter (where rating = 3)::int as stars_3, count(*) filter (where rating = 2)::int as stars_2,
    count(*) filter (where rating = 1)::int as stars_1
  from public.testimonials where is_published and product_id is not null group by product_id;
grant select on public.product_ratings to anon, authenticated;
grant all on public.product_ratings to service_role;

create table public.podcast_episodes (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique, title text not null, description text not null default '',
  audio_url text not null, cover_image_url text, duration_label text,
  is_published boolean not null default false, published_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create trigger podcast_touch before update on public.podcast_episodes for each row execute procedure public.touch_updated_at();
grant select on public.podcast_episodes to anon;
grant select, insert, update, delete on public.podcast_episodes to authenticated;
grant all on public.podcast_episodes to service_role;
alter table public.podcast_episodes enable row level security;
create policy "podcast read" on public.podcast_episodes for select to anon, authenticated using (is_published or public.has_role(auth.uid(),'admin'));
create policy "podcast admin" on public.podcast_episodes for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

-- 4. The 25 products
insert into public.products (slug,type,title,subtitle,description,cover_image_url,price_cents,is_free,is_lead_magnet,is_featured,buy_url,position) values
('cut-and-go','ebook','Cut and Go','The Mobile Barbers Playbook for Building a Mobile Empire','This book is a complete blueprint for barbers who want to break free from the traditional shop model and build a successful mobile barber business. It explains why mobile barbering is one of the fastest-growing opportunities in the industry, giving professionals more freedom, flexible schedules, higher earning potential, and direct access to premium clients who value convenience. Readers will learn how to choose and design the right mobile setup, from vans and trailers to portable event stations, while creating a clean, professional experience clients trust. The book also covers licensing, insurance, legal protection, and the must-have tools needed to deliver high-quality cuts on the go. Beyond operations, it teaches branding strategies to turn your vehicle into a rolling advertisement and build a recognizable business that stands out. Marketing chapters show how to attract clients through social media, Google listings, referrals, and local partnerships. Readers will also master booking systems, route planning, and scheduling to maximize time and profits. The client experience is a major focus, teaching how to create luxury-level service, build loyalty, and generate repeat customers. Advanced chapters explore weddings, VIP events, corporate contracts, and pop-up opportunities that can dramatically increase income. Finally, the book reveals how to grow from one vehicle into a fleet, hire other barbers, create systems, and build a long-term brand that generates wealth. Whether you’re a beginner or experienced barber, this guide shows how to transform your skills into a mobile empire.','https://public-files.gumroad.com/7eg35f1wzem2mtca5c5na2hl0fjf',2399,false,false,false,'https://www.gswau.com/l/qegay',0),
('cutting-edge-leadership','ebook','Cutting Edge Leadership','Strategies for Managing a Thriving Salon or Barbershop','Cutting Edge Leadership: Strategies for Managing a Thriving Salon or Barbershop is a practical guide for owners, managers, and aspiring leaders who want to build a successful business through strong leadership, not just great services. This book teaches that the true foundation of any thriving salon or barbershop is the person leading it. Readers will learn how to define their leadership style, create a winning culture, and build a team-first environment where staff feel respected, motivated, and committed to growth. The book covers every major leadership challenge, including hiring the right people, training for consistency, improving communication, and learning how to motivate different personalities. It also explains how to delegate effectively, create accountability, and stop carrying the entire business alone. Financial leadership is another key focus, helping owners understand pay structures, bonuses, retention strategies, and how to reward top performers while protecting profits. Readers will also learn how to handle conflict, navigate crises, fire respectfully, and stay calm under pressure. Advanced chapters show how to develop future leaders within the team, conduct productive performance reviews, and create clear growth paths for staff. More than a management book, this is a blueprint for building a respected brand, loyal team, and lasting legacy. It teaches how to lead with confidence, integrity, and vision while creating a shop that grows beyond the chair.','https://public-files.gumroad.com/77w3ui1shx77kv53h4p02a4984w6',3799,false,false,true,'https://www.gswau.com/l/hapsir',1),
('cut-the-noise','ebook','Cut The Noise','The Barbers & Stylists Guide To Listening Behind The Chair','Cut The Noise: The Barber and Stylist’s Guide to Listening Behind the Chair is the game-changing book the beauty industry has been missing. Beyond the fade and the finish, what truly separates good barbers from great ones is the ability to really listen. This guide takes you deep into the art of active listening — teaching you how to read body language, decode what clients aren’t saying, ask questions that build genuine trust, and create an atmosphere where people feel safe and valued. From handling nervous first-timers to managing difficult conversations with grace, every chapter equips you with real, practical tools to elevate your client experience. Learn how silence can be your strongest asset, how listening drives loyalty, and how one meaningful conversation can turn a walk-in into a lifelong client. Whether you’re behind the chair or leading a team, this book will transform the way you connect. Because the most powerful tool in your shop isn’t your clippers — it’s your ears.','https://public-files.gumroad.com/il9cqyp9vredcy4wnrs19vpaa1vh',2399,false,false,false,'https://www.gswau.com/l/lwgncp',2),
('cutting-stress-not-just-hair','ebook','Cutting Stress, Not Just Hair','A Barber’s & Stylist’s Burnout Survival Guide','Cutting Stress, Not Just Hair: A Barber and Stylist’s Burnout Survival Guide is the honest, no-nonsense book this industry has needed for a long time. From the outside, life behind the chair looks glamorous — the creativity, the community, the craft. But the reality tells a different story. The long hours on your feet, the physical strain on your body, the emotional weight of client conversations, and the constant pressure to perform at your best every single day takes a serious toll. Burnout isn’t a personal failure — it’s a predictable result of an industry that too often glorifies the grind and ignores the human behind the scissors. This guide is your roadmap back to yourself. You’ll learn how to spot the early warning signs of burnout before they cost you your career — the chronic exhaustion, the cynicism, the loss of joy in work you once loved. You’ll understand the gap between the polished highlight reel of social media and the real, emotionally draining week happening behind the scenes. And most importantly, you’ll get the practical tools to do something about it. From setting firm boundaries without guilt, to protecting your body with ergonomic habits and daily mobility routines — this book covers it all. Discover how to work smarter with better pricing strategies, build rest into your schedule without losing momentum, and handle clients who bring heavy emotional baggage to your chair without carrying it home with you. But this isn’t just about surviving — it’s about thriving. You’ll reignite your creative spark, design a long-term career path that prioritizes your health and well-being, and learn how to build a shop culture that lifts the next generation up instead of burning them out. Whether you’re running on empty right now or just starting to feel the weight of the grind, this book will meet you exactly where you are and walk you toward a career that lasts. Your passion brought you to this industry. This guide will help you stay.','https://public-files.gumroad.com/uwhqmjxsxi5h3sm8nfmls30buwc3',2399,false,false,false,'https://www.gswau.com/l/ldkcz',3),
('from-posts-to-profits','ebook','From Posts to Profits','Building Your Brand Online As A Barber Or A Stylist','From Post To Profits: Building Your Brand Online as a Barber or Stylist is the ultimate digital playbook for beauty professionals who are ready to turn their social media presence into a real, thriving business. In today’s world, your next client isn’t finding you through word of mouth alone — they’re scrolling, searching, and making decisions about you before they ever send that first DM. The question is: what are they finding when they look? This guide takes you step by step through everything you need to build a powerful, profitable online brand from the ground up. You’ll start by auditing your current digital presence and defining what makes you uniquely you — your voice, your energy, your aesthetic, and the story only you can tell. From crafting the perfect bio to building a full brand board, you’ll walk away knowing exactly who you are online and who you’re speaking to. You’ll learn how to identify your ideal client, choose the right platforms for your brand, and create content that actually converts — not just gets likes. Discover the power of before-and-after transformations, behind-the-scenes content, client spotlights, and video Reels that stop the scroll and fill your booking calendar. Master hashtags, captions, and the algorithm so your work gets seen by the people who matter most. But this book goes beyond just posting. You’ll learn how to turn DMs into booked appointments, collect glowing reviews that build instant trust, and set up seamless booking systems that work even while you sleep. And when you’re ready to scale, you’ll explore how to grow from stylist to CEO — with digital courses, product lines, and a brand that extends far beyond the chair. Consistency beats clout every single time. This book will show you how to build a sustainable online strategy that grows with you — without burning you out. Your chair is your stage. Your phone is your megaphone. Now it’s time to use both with purpose.','https://public-files.gumroad.com/nuezotlqpvjpy27ovan4ecayz47t',2399,false,false,false,'https://www.gswau.com/l/utepuj',4),
('from-walk-in-to-locked-in','ebook','From Walk-In to Locked In','How Barbers and Stylists Can Turn First Time Clients into Loyalists','This book is a powerful, practical roadmap for barbers and stylists who want to stop chasing clients and start keeping them — for life. Across 15 carefully crafted chapters, it walks you through every touchpoint of the client experience, from the moment someone walks through your door to the moment they’re raving about you to their friends. Whether you’re a mobile barber, shop owner, or independent stylist, this guide treats your craft not just as a skill — but as a business, a relationship, and a legacy. It starts before the first cut. The opening chapters zero in on the Golden 60 Seconds — that critical window when a new client decides whether they trust you. You’ll learn how to engineer your environment, your energy, and your greeting to make every walk-in feel like a VIP. Then comes the consultation — the most underrated skill in the industry. Asking the right questions before you pick up a clipper prevents misunderstandings, saves money, and builds instant trust. Confidence during the cut is contagious. The book explores how your vibe behind the chair directly impacts how your client feels in it — and how narrating your process, handling feedback gracefully, and moving with intention positions you as a true professional. The mirror reveal is treated as the emotional climax of the entire appointment, and you’ll learn how to present your work with pride while planting seeds for the next visit. Emotional intelligence separates good barbers from great ones. A full chapter dives into reading the room, navigating sensitive conversations, and protecting your energy — because true loyalty is built not just through skill, but through making people feel genuinely seen and respected. From there, the book gets deeply practical. You’ll build repeatable systems using the “3 P’s” — Professionalism, Presence, and Personalization. You’ll master the art of remembering client names, styles, and stories. You’ll learn how to rebook confidently, follow up within 24 hours, and create a sensory environment that clients want to photograph and share. Not every client is your client. The book teaches you to recognize different personalities, spot red flags early, and professionally decline relationships that drain your energy. And when mistakes happen — because they will — you’ll have the scripts and mindset to turn errors into loyalty-building moments. The final chapters make the case that retention always beats volume. A focused, loyal clientele is more profitable than constantly chasing walk-ins. You’ll learn how to generate referrals naturally, fill your books during slow seasons, and build the kind of demand that makes clients happy to wait for you. This book ends where every great career should — with legacy. Not just a full calendar, but a reputation, a community, and a career that truly means something. This isn’t just about hair. It’s about building a business that runs on trust — one client at a time.','https://public-files.gumroad.com/ki3hkocaa5ewngnxrq4sn2s0pqi8',2399,false,false,false,'https://www.gswau.com/l/hhgwvd',5),
('haircuts-without-the-headaches','ebook','Haircuts Without The Headaches','','This book is the survival guide every barber and stylist needs but rarely gets. While most industry training focuses on technique — the perfect fade, the flawless color — this one tackles something far more complex: the human side of the business. The conversations, the conflicts, the complaints, and the emotional weight that comes with serving people for a living. Across 10 powerful chapters, it equips you with the mindset, the scripts, and the strategies to handle every difficult situation behind the chair with professionalism, confidence, and grace. It starts where every service starts — the first impression. But beyond the warm welcome, it teaches you to read the room immediately. Is this client going to be cooperative, or are there warning signs hiding in plain sight? Something as simple as how they talk about their last barber can tell you everything you need to know before you even pick up a clipper. The book teaches you to trust those instincts and act on them early. From there, it introduces you to the most common problem client personalities — the Chronic Complainer, the Micromanager, the Vague Visionary, the Entitled One, and the dreaded No-Show Repeat Offender. Each type is broken down with real-world examples and proactive strategies so you’re never caught off guard. Knowing who’s sitting in your chair changes everything about how you approach the service. Active listening is the skill that holds it all together. Truly hearing your client goes far beyond nodding along. It means repeating details back for confirmation, decoding vague requests like “just a little off the top,” and using photo references to eliminate guesswork. When communication is crystal clear from the start, complaints become rare and trust builds naturally. But when clients are difficult — and they will be — you’ll learn how to stay professional no matter what. Breathing techniques, mindful body language, and verbal judo give you practical tools to de-escalate tension without losing your composure or your authority. Complaints, when handled correctly, can actually strengthen loyalty. The book walks you through a four-step recovery process — apologize, acknowledge, offer a solution, and follow up — showing how a dissatisfied client can become your most passionate supporter when you respond with calm and genuine care. Boundaries are not optional — they are your business. You’ll find real scripts for saying no politely, communicating your policies from day one, and confidently handling requests for discounts or extra services without compensation. Consistent boundaries don’t drive good clients away. They attract better ones and filter out the ones who were never a right fit to begin with. Sometimes, the relationship simply has to end. The book gives you the language and the courage to professionally part ways with clients who are damaging your well-being — without unnecessary drama, without guilt, and without putting your reputation at risk. It also addresses the modern challenge of online reviews and social media conflicts, offering clear response templates and guidance on when to engage publicly and when silence is the stronger move. The final chapters bring it all home — reminding you that you don’t have to carry the weight of difficult clients alone. Team support, shared policies, and strong leadership all play a role in creating a healthier work environment. And perhaps most importantly, the book closes with a deep focus on your mental health — helping you recognize burnout before it takes over, build daily routines that keep you grounded, and remember that your peace is not a luxury. It is the foundation everything else is built on. Technical skill gets you in the door. Emotional intelligence keeps you in business — and keeps you well while you’re doing it.','https://public-files.gumroad.com/vta6yo4gs4g6fpitbp7fsc8cvf82',2399,false,false,false,'https://www.gswau.com/l/jtkqe',6),
('inventory-management-for-barbershops-and-salons','ebook','Inventory Management for Barbershops and Salons','','Your Guide to Painless Inventory for Barbershops and Salons You’re a pro behind the chair — but the business side? That’s where most barbers and stylists struggle. This book fixes that. Across 13 practical chapters, it breaks down everything you need to know about managing your products, tools, and supplies without the stress, the waste, or the guesswork. From categorizing your backbar and retail products to setting smart par levels, building reorder schedules, and running regular audits — every system is laid out in simple, actionable steps. You’ll learn how to stop over-ordering, eliminate waste, negotiate with vendors, and turn your retail shelf into a serious income stream that can boost revenue by 15-25% or more. It also tackles the tough stuff — theft prevention, team accountability, tool maintenance, and scaling your system when you’re ready to grow. Whether you’re a solo mobile barber or managing a multi-chair shop, this guide meets you where you are. The bottom line is simple: inventory chaos costs you money, clients, and peace of mind. But with the right systems in place, you’re not just a talented barber or stylist anymore. You’re a CEO who knows their numbers — and that changes everything.','https://public-files.gumroad.com/kqhpzv3coc6c0xg1g7bnmwcbm036',2399,false,false,false,'https://www.gswau.com/l/ujqfk',7),
('its-more-than-just-a-haircut-use-product-selling-principles','ebook','Its more than just a haircut use product selling principles','','The service doesn’t end when your client leaves the chair — and this book makes that crystal clear. Across 12 focused chapters, it teaches barbers and stylists how to naturally recommend the right products, build genuine client trust, and boost retail income without ever feeling pushy, awkward, or salesy. This is the guide that bridges the gap between a great haircut and a great hair day — every single day. It starts with a simple but powerful truth: your clients go home and struggle to recreate what you just did. The style falls flat. The texture disappears. The confidence fades. The right product recommendation closes that gap and positions you as more than a skilled technician — it makes you a trusted hair advisor who shows up for your clients even when they’re not in your chair. From understanding buyer psychology to planting seeds early in the consultation, every chapter gives you real scripts, practical techniques, and honest strategies. You’ll learn how to read body language, ask the right questions, and introduce products naturally mid-service — long before the client is heading for the door. The book teaches you to think like a hair doctor: diagnose the problem, then prescribe the solution. You’ll learn how to customize recommendations by hair type and lifestyle, demonstrate products chairside so clients can see and feel the results firsthand, handle objections with empathy, and design a retail space that invites browsing and encourages buying. It even covers building simple take-home routines that clients will actually follow, and how to follow up after the appointment to reinforce your recommendations and strengthen the relationship. The message throughout is consistent and clear — prescribe, don’t push. When your recommendations come from a place of genuine expertise and real care, clients don’t feel sold to. They feel guided, supported, and empowered. And empowered clients rebook, refer friends, and buy — every single time.','https://public-files.gumroad.com/00vawq1tectaok8vj6nbfh2bdypw',2399,false,false,false,'https://www.gswau.com/l/vybnes',8),
('beauty-barber-business-bootcamp','ebook','Beauty & Barber Business Bootcamp','','This book is a powerful guide for anyone who wants to transform their passion for barbering, hairstyling, or beauty services into a successful business. It walks readers through the full journey of building a brand from the ground up, starting with discovering their vision, defining their purpose, and understanding the type of clients they want to serve. It helps aspiring owners move beyond simply mastering their craft and step confidently into leadership, teaching the mindset, discipline, and business awareness needed to succeed. Readers will gain practical insight into choosing the right business model, selecting the best location, creating an attractive and professional environment, and handling the legal and financial foundations necessary for long-term stability. From startup costs and budgeting to pricing services strategically, the book provides the knowledge needed to make smart decisions and avoid common mistakes that can slow growth. It also focuses heavily on branding and marketing, showing how to create a memorable identity, attract attention online and offline, and generate excitement before opening day. Readers learn how to build a strong team, create excellent customer experiences, and develop systems that keep operations smooth, organized, and profitable. More importantly, this book teaches how to grow from being the person behind the chair into becoming a true CEO. It explores delegation, leadership, scaling strategies, expansion opportunities, and ways to create multiple income streams through products, education, and digital platforms. Whether someone wants to open their first shop, launch a mobile service, grow an existing business, or build lasting wealth in the beauty industry, this book delivers the mindset and strategies needed to make it happen. It is a blueprint for building success, freedom, and legacy through talent, vision, and smart business execution.','https://public-files.gumroad.com/u6qabh0jpmuf2e064z4cueq1hnox',4799,false,false,true,'https://www.gswau.com/l/rcdle',9),
('before-the-cut','ebook','Before The Cut','Mastering Client Consultation for Every Barber and Stylist','Before The Cut: Mastering Client Consultation is a powerful guide for barbers and stylists who want to elevate their craft through communication. It teaches how to build trust, ask better questions, listen deeply, manage expectations, and customize every service to the client. Readers learn that great results begin before the first snip, turning consultations into stronger relationships, repeat business, referrals, and long-term success behind the chair.','https://public-files.gumroad.com/yaev3906pkdgctfndpgyklhcv8o4',2399,false,false,false,'https://www.gswau.com/l/xrmoc',10),
('booked-and-busy','ebook','Booked and Busy','Marketing Strategies to Grow Your Salon or Barbershop','This book is a complete marketing and growth guide for salon and barbershop owners who want to attract more clients, increase bookings, and build a recognizable brand. It teaches readers how to create a strong business identity through branding, define their ideal customer, and position their services to stand out in a crowded market. From logos, messaging, and shop atmosphere to pricing and promotions, the book shows how every detail can influence client loyalty and business success. Readers will learn how to use social media platforms like Instagram, TikTok, and Facebook to turn content into paying customers through strategic posting, engaging captions, reels, and location-based visibility. It also explains how to build a professional website, improve online booking systems, and optimize Google Business Profile so potential clients can easily find and book appointments. Local SEO, reviews, and referrals are covered to help businesses rank higher and earn trust quickly. Beyond attracting new customers, this book focuses heavily on retention. It teaches how to create an unforgettable client experience, develop loyalty programs, run profitable packages, and use email or SMS marketing to stay connected and top-of-mind. Readers will also discover how to host community events, collaborate with influencers, partner with local businesses, and build word-of-mouth momentum that drives long-term growth. The book is designed to be practical and action-focused, giving clear steps for both new and established beauty businesses. It also addresses mindset, consistency, and how to create simple monthly marketing systems that keep results coming over time. Whether you are launching a new salon, growing a barbershop, or trying to fill slow days, this guide gives you the tools to become more visible, more booked, and more profitable. Perfect for beauty professionals who want real strategies instead of guesswork, this book helps transform talent into a thriving business. It is a roadmap for building a loyal client base, stronger reputation, and a brand that people remember.','https://public-files.gumroad.com/4x9jpoab8wd6rje0l7ycrz5o03ca',3799,false,false,true,'https://www.gswau.com/l/hhrkha',11),
('crafted-by-the-chair','ebook','Crafted by the Chair','A Barber’s Transformation from Apprentice to Becoming a Master Barber','This book is a complete roadmap for anyone who wants to build a successful career in barbering—from beginner to master barber. It goes far beyond learning how to cut hair by teaching the mindset, discipline, technical skills, business knowledge, and leadership needed to thrive in the industry. Readers will learn how to discover their purpose, develop professionalism, master fades, lineups, shaves, beard work, consultations, client communication, speed, precision, and signature styles that make them stand out. The book also breaks down the business side of barbering, including pricing, branding, marketing, booking systems, client retention, referrals, finances, and scaling into shop ownership or multiple income streams. It teaches how to create a personal brand, use social media effectively, build loyal clientele, and turn barbering skills into long-term wealth and freedom. Beyond the chair, it explores mentorship, teaching others, community impact, partnerships, content creation, and expanding influence outside the shop. It emphasizes character, consistency, hygiene, work ethic, and leaving a positive legacy in the barber industry. Whether you are just starting, currently apprenticing, or already cutting hair and wanting to level up, this book provides practical strategies, drills, systems, and real-world wisdom to sharpen both your craft and your career. It is not just about becoming a better barber—it is about becoming a respected professional, entrepreneur, and leader whose name carries value for years to come.','https://public-files.gumroad.com/pjqbc4u9esxw52b6rwr3uaw05d6j',2399,false,false,false,'https://www.gswau.com/l/xnljkc',12),
('gswau-barber-success-bundle','bundle','GSWAU Barber Success Bundle','','Stop leaving money on the table. The GSWAU Barber Success Bundle gives you 5 powerful books that turn talented barbers and stylists into real business owners. Get: • Booked and Busy (Marketing that fills chairs) • From Posts to Profits (Build your brand online) • Before The Cut (Master client consultations) • Cutting Edge Leadership (Run a thriving shop) • Cut and Go (Mobile barber playbook) Everything you need to get booked, build loyalty, and make money beyond the chair. Normally much more — now only $97. Instant download. Start winning today.','https://public-files.gumroad.com/2ae363e40t0iavkw1bgqlnef3f9i',9700,false,false,true,'https://www.gswau.com/l/tvmee',13),
('first-impressions-matter','ebook','First Impressions Matter','Free Chapter','Download “First Impressions Matter” from Before The Cut — free. Learn how your grooming, station, tone, and presence already tell clients everything they need to know. Instant PDF — no spam, just one powerful chapter.','https://public-files.gumroad.com/k2uqxooxz0uuclnppyjk3iqnhit9',0,true,true,false,'https://www.gswau.com/l/zziiqx',14),
('no-english-no-problem','ebook','No English No Problem','Mastering Nonverbal and Visual Communication in the Shop','Mastering Nonverbal Communication for Barbers and Stylists In today’s diverse world, your clients don’t always speak your language — but that should never stop you from delivering an exceptional experience. Across 12 powerful chapters, this book teaches barbers and stylists how to communicate confidently and effectively without saying a single word. From mastering gestures and reading body language to building visual style boards, using digital translation tools, and designing an inclusive shop environment, every chapter gives you practical skills to bridge any language gap with professionalism and warmth. You’ll learn how to conduct a full client consultation using nothing but photos, hand gestures, and mirror confirmations — and how to spot and fix miscommunication before it becomes a bad haircut. The book also tackles the emotional side — understanding what a nervous, non-English-speaking client feels when they sit in your chair, and how simple acts of patience, calm energy, and genuine care speak louder than any words ever could. Whether you’re serving immigrants, tourists, or anyone who feels more comfortable staying quiet, this guide turns what most barbers see as a barrier into your biggest competitive advantage. Because when you can connect with anyone — regardless of language — you don’t just build a clientele. You build a community.','https://public-files.gumroad.com/hbrolvoc25jxb25s08yz9uhbdclx',2399,false,false,false,'https://www.gswau.com/l/qdyeq',15),
('polished-presence','ebook','Polished Presence','Building A Brand That Cuts Through The Noise','Your skills get clients in the chair. Your brand keeps them coming back — and this book shows you exactly how to build one that lasts. Across 12 powerful chapters, it walks barbers and shop owners through every layer of brand building, from defining your core identity all the way to protecting and scaling your legacy as your business grows. It starts with a truth most barbers overlook: clients don’t just buy a haircut. They buy a feeling. A vibe. A promise. Your brand is that promise — and without one, you’re just another room with chairs. No loyalty. No premium pricing. No lasting reputation. The book opens by reframing how you see branding entirely, making clear that it’s not just a logo or a color scheme — it’s the psychology behind every single interaction you have with a client. From there, it guides you step by step. You’ll define your vision, mission, and core values. You’ll discover your niche — because trying to be everything to everyone means being nothing to nobody. You’ll craft a shop name that’s memorable, unique, and aligned with who you are, then build a visual identity with intentional colors, logos, and brand guidelines that create instant recognition and trust. Your brand voice gets its own chapter — because how you text a client, caption an Instagram post, or respond to a complaint all reflect who you are as a business. Consistency in your voice builds credibility. And credibility builds loyalty. The book goes beyond the digital and into the physical — teaching you how to design your shop space as a branding tool in itself. Lighting, music, furniture, and even the scent of your shop all contribute to the experience your clients carry with them long after they leave. Every sensory detail is an opportunity to reinforce who you are. You’ll also learn how to align your personal brand with your business identity, build a team that embodies your values, and create systems that deliver the same exceptional experience every single time — whether you’re behind the chair or not. And when it’s time to evolve, the book has you covered — guiding you through a confident rebrand without losing the loyal clients you’ve already earned. A brand built right today doesn’t just fill your calendar. It creates income, commands respect, and builds a legacy that outlives you.','https://public-files.gumroad.com/s4ilskq9vytb2ciu6meyicy1w464',2399,false,false,false,'https://www.gswau.com/l/qnylyd',16),
('rent-the-chair-or-own-the-shop','ebook','Rent the Chair or Own the Shop','Making the Right Move in Your Career','Booth Rental vs. Ownership — Choosing the Right Path for Your Career Every barber and stylist reaches a point where the chair starts feeling too small. The question is — what’s your next move? Across 13 focused chapters, this book helps beauty professionals make one of the most important career decisions of their lives with clarity, confidence, and a clear-eyed understanding of what each path truly demands. It starts where every smart decision starts — with self-awareness. Before you sign a lease or rent a chair, you need to know who you are, what drives you, and where you want to be in one, three, and five years. From there, the book breaks down both paths honestly and thoroughly — the freedom and flexibility of booth rental, and the power and pressure of full ownership — without romanticizing either one. Every chapter delivers practical, real-world guidance. You’ll compare income models, understand tax and legal obligations, navigate lease negotiations, build your brand, and learn what it actually takes to lead a team. Location strategy, scaling plans, and the psychology of your workspace all get their own dedicated attention. Real stories from professionals who rented, owned, downsized, and pivoted bring the lessons to life — raw, relatable, and refreshingly honest. The book closes with a personalized decision matrix to help you weigh your options based on your unique situation, not someone else’s blueprint. Because there’s no single right path in this industry. There’s only the one that’s right for you — and this book helps you find it.','https://public-files.gumroad.com/6u1w0ngzj1yf02vx21l03lk9euym',2399,false,false,false,'https://www.gswau.com/l/flras',17),
('the-art-of-building-your-clientele-in-the-barber-and-beauty-industry','ebook','The Art of Building Your Clientele in the Barber and Beauty Industry','','Building a Thriving Career in the Barber and Beauty Industry. This book is your complete roadmap to building not just a full client base — but a lasting, fulfilling career that stands the test of time. Across 10 practical chapters, it covers every dimension of what it truly takes to succeed behind the chair, from the very first impression all the way to long-term financial planning and avoiding burnout. It opens where every client relationship begins — that split-second first impression. Your appearance, your energy, your greeting, and your environment all speak before you ever pick up a clipper. From there, it guides you through building a professional persona that’s uniquely yours, finding your specialty, and showing up consistently both online and in person. Consistency is treated as a superpower throughout the book. Clients return to barbers and stylists they can predict and trust — and you’ll learn how to build systems, routines, and communication habits that make every experience feel reliable and intentional. The book then dives into growing your business organically — through referrals, social media content, community involvement, and loyalty programs that make clients feel genuinely valued. You’ll also learn how to price your services with confidence, handle difficult clients professionally, and respond to reviews in a way that protects your brand. The final chapter zooms out — encouraging you to track your numbers, invest in your education, diversify your income streams, and plan for your future. Because a great barber builds a great career — but a smart barber builds a great life.','https://public-files.gumroad.com/g75ackybbyho799mj0ntddq3kxlm',2399,false,false,false,'https://www.gswau.com/l/ishjl',18),
('the-barbers-toolkit','ebook','The Barbers Toolkit','','A Barber’s Complete Guide to Tools, Maintenance, and Mastery. Your skills are only as good as the tools in your hands — and this book makes sure those tools are always ready to perform. Across 10 focused chapters, it walks barbers at every level through everything they need to know about their gear, from building the perfect starter kit to embracing the latest innovations in barbering technology. It starts with the essentials — clippers, shears, razors, edgers, combs, and brushes — breaking down each tool’s purpose, strengths, and best use cases so you can build a kit that truly matches your style and technique. Whether you’re a beginner figuring out your first setup or a seasoned pro looking to level up, every chapter meets you where you are. From there, the book goes deeper — covering blade maintenance, daily and weekly cleaning routines, proper sanitation, and how to organize your station for maximum efficiency and flow. Because a clean, organized workspace isn’t just professional — it’s a direct reflection of your brand. Specialized chapters tackle fades, beard sculpting, mobile setups, and the smart decision of when to repair versus replace aging tools. The book closes with a fascinating look at how barbering technology has evolved — from classic straight razors to quiet motors, wireless charging, and vacuum clipper systems. Because behind every great cut is a barber who respects their craft — and that starts with knowing, caring for, and mastering every single tool in their hands.','https://public-files.gumroad.com/mvvy9nogp9vg0blpo8yzaxlmh5ys',2399,false,false,false,'https://www.gswau.com/l/slmnpv',19),
('the-legacy-of-the-chair','ebook','The Legacy of the Chair','Passing Skills, Standards, and Style to the Next Generation for Barbers and Stylists','A Complete Guide to Mentorship in the Barber and Beauty Industry. This book is for every barber and stylist who has mastered their craft and is ready to pass it on. Across 12 powerful chapters, it builds a complete mentorship system — from teaching core technical skills all the way to creating a lasting legacy that outlives your time behind the chair. It opens with a truth the industry doesn’t talk about enough: mentorship isn’t just generous — it’s essential. It preserves standards, strengthens reputations, builds better teams, and protects the culture of the craft. From there, it guides experienced barbers and stylists through every stage of the mentorship journey — understanding how people learn, developing the right mindset, teaching with structure, instilling professionalism, and building confidence in someone who is just finding their voice. Every chapter is packed with practical tools — lesson plan templates, skills matrices, feedback frameworks, sanitation drills, consent scripts, and confidence ladders — so mentorship never feels vague or overwhelming. You’ll learn how to give feedback that lands, handle mistakes with calm and purpose, teach your signature techniques without cloning yourself, and prepare your mentee for full career independence. The final chapter elevates the entire conversation — pushing you to codify your knowledge, train other mentors, and launch a legacy project that keeps your craft alive for generations to come. Because the greatest cut you’ll ever make isn’t on a client. It’s in the career of someone you believed in.','https://public-files.gumroad.com/trz6xs324mem8pdcf187iuruw5h2',2399,false,false,false,'https://www.gswau.com/l/rvcob',20),
('the-people-s-shop','ebook','The People’s Shop','Designing a Place Where Clients Feel At Home','More Than a Haircut: Building an Inclusive, Community-Centered Barbershop The most successful barbershops have always been more than places to get a cut — they’ve been community hubs, safe spaces, and neighborhood landmarks. Across 12 powerful chapters, this book shows you exactly how to build that kind of shop intentionally, with systems, culture, and values that make every single client feel genuinely welcome from the moment they walk through the door. It covers every layer of the client experience — from your exterior signage and lighting to your greeting scripts, seating comfort, playlist strategy, and the words you use in the chair. You’ll learn how to serve every hair type with confidence, use inclusive language, handle complaints professionally, and design a physical space that works for clients with disabilities, sensory needs, and diverse cultural backgrounds. Beyond the individual experience, the book builds outward — helping you curate décor that reflects your community, host events that create real impact, build a team that lives your values, and establish partnerships that extend your shop’s reach far beyond your four walls. Every chapter is packed with action plans, role-play exercises, quick checklists, and ready-to-use templates so that nothing stays theoretical. This is a hands-on guide built for immediate results. The message throughout is clear and consistent: inclusivity isn’t a trend or a marketing strategy. It’s the foundation of a thriving, loyal, and respected business. Because when everyone feels welcome in your chair, everyone keeps coming back.','https://public-files.gumroad.com/bmphrimq1bwn3b5dibmiy11r13y0',2399,false,false,false,'https://www.gswau.com/l/cuizyr',21),
('the-price-shift','ebook','The Price Shift','A Barbers and Stylist’s Guide to Price Increase By G.S. W. Augustin','Know Your Worth: The Barber and Stylist’s Complete Guide to Confident Pricing Undercharging isn’t humility — it’s a habit that quietly drains your energy, your income, and your passion for the craft. Across 14 focused chapters, this book gives barbers and stylists everything they need to price their services with confidence, communicate increases without apology, and build a business that genuinely reflects their value. It starts where every pricing problem starts — in your head. Fear of losing clients, guilt around money, and imposter syndrome are real barriers, and this book tackles them head-on with mindset work, affirmations, journaling exercises, and real stories from professionals who raised their prices and watched their businesses grow. From there, it dives into the psychology of pricing — why higher prices actually build trust, why discounting devalues your brand, and how your price tag communicates your positioning before a client ever sits down. You’ll learn exactly when to raise your prices, how to calculate your real hourly cost, how to structure packages and memberships, and how to communicate increases to clients with scripts that are direct, confident, and never apologetic. The book also prepares you for pushback — with ready-to-use responses for every objection — and gives you permission to gracefully release clients who no longer fit your business. Branding, image, service upgrades, tracking key metrics, and planning for future increases round out a guide that’s as practical as it is empowering. Because charging what you’re worth isn’t about money. It’s about respect — for your craft, your time, and your legacy.','https://public-files.gumroad.com/30zgkurwriqzxlwlkvsd1t98ckfu',2399,false,false,false,'https://www.gswau.com/l/ogijmt',22),
('the-science-of-the-scalp-behind-the-chair','ebook','The Science of the Scalp Behind the Chair','','Beneath the Cut: The Barber and Stylist’s Complete Guide to Scalp Health Most barbers and stylists are trained to perfect the cut — but few are trained to truly understand what’s happening underneath it. Across 12 in-depth chapters, this book transforms the way beauty professionals see the scalp, turning everyday service into a genuine act of health-conscious care. It starts with a powerful truth: barbers and stylists are often the first people to notice changes on a client’s scalp — before a doctor, before a dermatologist, before anyone. That proximity is a responsibility, and this book gives you the knowledge to honor it. From understanding the anatomy of the scalp and hair follicle to recognizing common conditions like dandruff, psoriasis, folliculitis, ringworm, and the various forms of hair loss — every chapter builds your ability to see what others miss and respond with confidence and professionalism. You’ll learn how stress, hormones, diet, medications, and even product buildup show up on the scalp, and how to open those conversations with clients in a way that feels caring rather than alarming. The book also covers chemical and heat damage, texture-specific scalp needs, proper sanitation practices, and when to gently refer a client to a medical professional. Natural remedies, professional scalp treatments, and strategies for adding scalp health services to your menu round out a guide that’s as business-savvy as it is educational. Because the best barbers and stylists don’t just perfect the look on top. They understand and protect everything beneath it.','https://public-files.gumroad.com/jtwbk5smkxi8tyaqeylkukgugj2h',2399,false,false,false,'https://www.gswau.com/l/mcpys',23),
('profits-beyond-the-chair','ebook','Profits beyond the chair','','The Digital Barber: Building Your Brand, Business, and Income Online The barber game has changed — and this book makes sure you’re ahead of it. Across 10 action-packed chapters, it walks barbers through everything they need to build a powerful online presence, sell products, attract new clients, and create income streams that work even when they’re not standing behind the chair. It starts with the mindset shift: going digital isn’t optional anymore. Competition is fierce, clients expect convenience, and the barbers winning right now are the ones who’ve figured out how to turn their craft into a brand. From building a clean, professional website to setting up online booking, launching a product line, and mastering social media — every chapter gives you practical, step-by-step guidance without overwhelming technical jargon. You’ll learn how to sell physical products like pomades, oils, and branded merchandise, explore options like private label, affiliate marketing, and dropshipping, and even offer virtual consultations and online courses that generate income around the clock. Social media strategy, video content creation, email marketing, text campaigns, and client retention systems all get their own dedicated chapters — complete with real examples and beginner-friendly tools. The book closes by thinking big — global shipping, brand partnerships, passive income, and building a team to support your growing digital empire. Because the best barbers today aren’t just great with clippers. They’re building brands, businesses, and legacies that extend far beyond the chair.','https://public-files.gumroad.com/27m5l736zqa5hz9xnpm4xj4scc8r',2399,false,false,false,'https://www.gswau.com/l/coiqv',24) on conflict (slug) do nothing;

